def cross_section_norm(x: np.ndarray, method: str = "mad") -> np.ndarray:
    """截面标准化，三种方法可选"""
    if method == "mad":
        med = np.nanmedian(x)
        mad = np.nanmedian(np.abs(x - med))
        return (x - med) / (1.4826 * mad + 1e-8) if mad > 0 else np.zeros_like(x)
    elif method == "zscore":
        mu, std = np.nanmean(x), np.nanstd(x)
        return (x - mu) / (std + 1e-8) if std > 0 else np.zeros_like(x)
    elif method == "rank":
        valid = np.isfinite(x)
        out = np.full_like(x, np.nan)
        order = np.argsort(x[valid])
        ranks = np.empty(order.shape[0])
        ranks[order] = np.linspace(0, 1, order.shape[0])
        out[valid] = ranks
        return out * 2 - 1  # 映射到 [-1, 1]

def ema_smooth(hist, alpha=0.3):
    w = (1 - alpha) ** np.arange(len(hist)-1, -1, -1)
    return np.average(hist, axis=0, weights=w)

