def _cs_resid(y, x):
    m = np.isfinite(y) & np.isfinite(x)
    if int(m.sum()) >= 30:
        A = np.column_stack([x[m], np.ones(int(m.sum()))])
        coef, *_ = np.linalg.lstsq(A, y[m], rcond=None)
        out = y.copy(); out[m] = y[m] - A @ coef
        out[~m] = np.nan
        return out - np.nanmean(out)

